CREATE COLUMN TABLE "TEST_AP"."TRO1" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "DocObjType" INTEGER CS_INT NOT NULL , "DocEntry" INTEGER CS_INT NOT NULL , "DocLineNum" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50), "TranspQty" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "DocOrdNum" INTEGER CS_INT, PRIMARY KEY ("AbsEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TRO1_DOC_LINK_U" ON "TEST_AP"."TRO1" ( "AbsEntry" ASC, "DocObjType" ASC, "DocEntry" ASC, "DocLineNum" ASC )